'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var discreteUniform = require( '@stdlib/random/array/discrete-uniform' );
var pow = require( '@stdlib/math/base/special/pow' );
var cbrt = require( '@stdlib/math/base/special/cbrt' );
var floor = require( '@stdlib/math/base/special/floor' );
var filledarray = require( '@stdlib/array/filled' );
var add5 = require( '@stdlib/number/float64/base/add5' );
var shape2strides = require( '@stdlib/ndarray/base/shape2strides' );
var strides2offset = require( '@stdlib/ndarray/base/strides2offset' );
var descriptor = require( '@stdlib/ndarray/base/descriptor' );
var orders = require( '@stdlib/ndarray/orders' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var kernel = require( './../lib' );


// VARIABLES //

var TYPES = [
	'float64'
];
var ORDERS = orders();

/**
* Creates a benchmark function.
*
* @private
* @param {PositiveInteger} len - ndarray length
* @param {NonNegativeIntegerArray} shape - ndarray shape
* @param {string} xtype - input ndarray data type
* @param {string} vtype - output ndarray data type
* @param {string} order - memory layout
* @returns {Function} benchmark function
*/
function createBenchmark( len, shape, xtype, vtype, order ) {
	var opts;
	var st;
	var x;
	var y;
	var z;
	var w;
	var u;
	var v;
	var f;

	st = shape2strides( shape, order );
	opts = {
		'dtype': xtype
	};
	x = discreteUniform( len, -100, 100, opts );
	y = discreteUniform( len, -100, 100, opts );
	z = discreteUniform( len, -100, 100, opts );
	w = discreteUniform( len, -100, 100, opts );
	u = discreteUniform( len, -100, 100, opts );
	v = filledarray( 0.0, len, vtype );

	x = descriptor( xtype, x, shape, st, strides2offset( shape, st ), order );
	y = descriptor( xtype, y, shape, st, strides2offset( shape, st ), order );
	z = descriptor( xtype, z, shape, st, strides2offset( shape, st ), order );
	w = descriptor( xtype, w, shape, st, strides2offset( shape, st ), order );
	u = descriptor( xtype, u, shape, st, strides2offset( shape, st ), order );
	v = descriptor( vtype, v, shape, st, strides2offset( shape, st ), order );

	f = kernel( shape.length );
	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			f( x, y, z, w, u, v, add5 );
			if ( isnan( v.data[ i%len ] ) ) {
				b.fail( 'should not return NaN' );
			}
		}
		b.toc();
		if ( isnan( v.data[ i%len ] ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var len;
	var min;
	var max;
	var ord;
	var sh;
	var t1;
	var t2;
	var f;
	var i;
	var j;
	var k;

	min = 1; // 10^min
	max = 6; // 10^max

	for ( k = 0; k < ORDERS.length; k++ ) {
		ord = ORDERS[ k ];
		for ( j = 0; j < TYPES.length; j++ ) {
			t1 = TYPES[ j ];
			t2 = TYPES[ j ];
			for ( i = min; i <= max; i++ ) {
				len = pow( 10, i );

				sh = [ len/2, 2, 1 ];
				f = createBenchmark( len, sh, t1, t2, ord );
				bench( format( '%s:ndims=%d,len=%d,shape=[%s],xorder=%s,vorder=%s,xtype=%s,vtype=%s', pkg, sh.length, len, sh.join(','), ord, ord, t1, t2 ), f );

				sh = [ 1, 2, len/2 ];
				f = createBenchmark( len, sh, t1, t2, ord );
				bench( format( '%s:ndims=%d,len=%d,shape=[%s],xorder=%s,vorder=%s,xtype=%s,vtype=%s', pkg, sh.length, len, sh.join(','), ord, ord, t1, t2 ), f );

				len = floor( cbrt( len ) );
				sh = [ len, len, len ];
				len *= len * len;
				f = createBenchmark( len, sh, t1, t2, ord );
				bench( format( '%s:ndims=%d,len=%d,shape=[%s],xorder=%s,vorder=%s,xtype=%s,vtype=%s', pkg, sh.length, len, sh.join(','), ord, ord, t1, t2 ), f );
			}
		}
	}
}

main();
